<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {useRouter} from 'vue-router'
import {onAuthStateChanged} from 'firebase/auth'
import {getStagingClients} from '../integrations/firebase/stagingClient'
import {inboxList,inboxRead,type InboxItem} from '../integrations/firebase/coachInbox'
import type {StagingSession} from '../integrations/firebase/stagingSession'
import {romeParts} from '../features/bookings/bookingPolicy'
const props=defineProps<{session:StagingSession}>(),router=useRouter()
const open=ref(false),count=ref(0),rows=ref<InboxItem[]>([]),warning=ref(''),busy=ref(false),loaded=ref(false),mobile=ref(false)
const unreadRows=computed(()=>rows.value.filter(r=>!r.read));let alive=true,request=0,timer:ReturnType<typeof setInterval>|undefined,media:MediaQueryList|undefined,stopAuth:(()=>void)|undefined
const updateMedia=()=>{mobile.value=media?.matches===true}
async function refresh(full=open.value){const id=++request;try{const r=await inboxList(props.session.uid,full);if(alive&&id===request){count.value=r.unread;if(full){rows.value=r.rows;loaded.value=true}warning.value=''}}catch(e){if(alive&&id===request)warning.value='Notifiche non aggiornate. Riprova.'}}
function visible(){if(document.visibilityState==='visible'&&!busy.value)void refresh()}
function toggle(){open.value=!open.value;if(open.value)void refresh(true)}
async function read(ids:string[],navigate?:InboxItem){if(!ids.length||busy.value)return;busy.value=true;++request;try{await inboxRead(props.session.uid,ids);if(!alive)return;rows.value=rows.value.map(x=>ids.includes(x.id)?{...x,read:true}:x);count.value=Math.max(0,count.value-ids.length);if(navigate){open.value=false;await go(navigate)}}catch{if(alive)warning.value='Impossibile segnare la notifica come letta.'}finally{if(alive){busy.value=false;void refresh()}}}
async function go(row:InboxItem){const athlete=props.session.role==='atleta';open.value=false;if(row.kind==='sheet'||row.kind==='program'){await router.push('/piano');return}if(row.kind==='revision'||row.kind==='revision_reply'){await router.push(athlete?'/progressi':'/coach/progressi');return}if(row.kind==='support'){await router.push({path:'/impostazioni',query:{inboxSupport:'1'}});return}await router.push({path:athlete?'/prenotazioni':'/coach/prenotazioni',query:athlete?{inbox:row.id}:{date:romeParts(row.startMs).date,bookingId:row.bookingId}})}
async function select(row:InboxItem){if(row.read)await go(row);else await read([row.id],row)}
function esc(e:KeyboardEvent){if(e.key==='Escape')open.value=false}
onMounted(()=>{stopAuth=onAuthStateChanged(getStagingClients().auth,u=>{if(u?.uid!==props.session.uid){++request;rows.value=[];count.value=0;open.value=false;loaded.value=false}});media=window.matchMedia(props.session.role==='atleta'?'(min-width: 0px)':'(max-width: 900px)');updateMedia();media.addEventListener('change',updateMedia);document.addEventListener('visibilitychange',visible);window.addEventListener('focus',visible);window.addEventListener('keydown',esc);timer=setInterval(visible,60000);void refresh(false)})
onUnmounted(()=>{alive=false;++request;stopAuth?.();clearInterval(timer);media?.removeEventListener('change',updateMedia);document.removeEventListener('visibilitychange',visible);window.removeEventListener('focus',visible);window.removeEventListener('keydown',esc)})
const format=(n:number)=>new Date(n).toLocaleString('it-IT',{timeZone:'Europe/Rome',dateStyle:'short',timeStyle:'short'})
</script>
<template><Teleport to="#lf17-mobile-bell" :disabled="!mobile"><div class="lf17-bell-wrap"><button type="button" class="theme-square lf17-bell" :aria-label="count?`Notifiche: ${count} non lette`:'Apri notifiche'" :aria-expanded="open" title="Notifiche" @click="toggle"><svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg><span v-if="count>0" :key="count" class="lf17-badge">{{count>99?'99+':count}}</span></button></div></Teleport><Teleport to="body"><div v-if="open" class="lf17-inbox-overlay" @click.self="open=false"><section class="lf17-inbox-panel" role="dialog" aria-modal="true" aria-label="Centro notifiche"><header><div><h2>Notifiche</h2><small>{{count}} non lette</small></div><button type="button" class="lf17-close" aria-label="Chiudi notifiche" @click="open=false">✕</button></header><div class="lf17-inbox-actions"><button type="button" :disabled="busy" @click="refresh(true)">Aggiorna</button><button type="button" :disabled="busy||!unreadRows.length" @click="read(unreadRows.map(x=>x.id))">Segna visibili come lette</button></div><p v-if="warning" role="status">{{warning}}</p><p v-if="!loaded&&!warning">Caricamento…</p><p v-else-if="loaded&&!rows.length">Non hai notifiche.</p><button v-for="n in rows" :key="n.id" type="button" :class="['lf17-inbox-row',{'is-unread':!n.read}]" :disabled="busy" @click="select(n)"><span class="lf17-dot" aria-hidden="true"/><span><strong>{{n.title}}</strong><small v-if="n.startMs">Appuntamento: {{format(n.startMs)}}</small><small>{{format(n.createdAt)}}</small></span><span aria-hidden="true">›</span></button><p v-if="count>50" class="lf17-inbox-hint">Ci sono altre notifiche non lette: segna quelle visibili e aggiorna.</p></section></div></Teleport></template>
<style scoped>.lf17-bell-wrap{display:flex;justify-content:flex-end;align-items:center;position:relative}.lf17-bell{position:relative;display:grid;place-items:center;min-width:40px;min-height:40px;padding:6px}.lf17-badge{position:absolute;top:-5px;right:-5px;min-width:20px;height:20px;padding:0 4px;border-radius:999px;background:#d92d3a;color:#fff;display:grid;place-items:center;font-size:11px;font-weight:800;line-height:1;border:1px solid white;animation:lf17-pop .6s ease-in-out 3}@keyframes lf17-pop{0%,100%{transform:scale(1)}50%{transform:scale(1.25)}}@media(prefers-reduced-motion:reduce){.lf17-badge{animation:none}}.lf17-inbox-overlay{position:fixed;inset:0;z-index:10010;background:#0006;display:flex;justify-content:flex-end;align-items:flex-start;padding:max(14px,env(safe-area-inset-top)) 14px;box-sizing:border-box}.lf17-inbox-panel{background:#fff;color:#17251c;width:min(100%,440px);max-height:85dvh;overflow:auto;border-radius:16px;padding:18px;box-shadow:0 16px 55px #0005;box-sizing:border-box}.lf17-inbox-panel header,.lf17-inbox-actions{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px}.lf17-inbox-panel h2{margin:0;color:inherit}.lf17-inbox-panel small{display:block;color:#53645b;margin-top:4px}.lf17-inbox-panel button{color:#174c32;background:#f3f7f4;border:1px solid #c9dcd0;border-radius:9px;padding:9px;font:inherit;cursor:pointer}.lf17-inbox-panel button:disabled{opacity:.5}.lf17-inbox-row{width:100%;display:grid;grid-template-columns:10px 1fr auto;text-align:left;align-items:start;gap:10px;margin-bottom:8px}.lf17-inbox-panel .is-unread{background:#e4f6e9;border-color:#98d4ab}.lf17-dot{width:8px;height:8px;border-radius:50%;margin-top:6px}.is-unread .lf17-dot{background:#218b50}.lf17-inbox-hint{font-size:12px}.lf17-close{min-width:38px;min-height:38px}</style>
<style>@media(max-width:390px){.mobile-topbar .top-actions:has(.lf17-bell-wrap){gap:5px}.mobile-topbar:has(.lf17-bell-wrap) .brand{gap:5px;min-width:0}.mobile-topbar:has(.lf17-bell-wrap) .brand img{width:34px;height:34px;flex-shrink:0}.mobile-topbar:has(.lf17-bell-wrap) .brand-name{font-size:17px}.mobile-topbar:has(.lf17-bell-wrap) .top-actions .theme-square{width:36px;min-width:36px;height:36px;min-height:36px}.mobile-topbar:has(.lf17-bell-wrap) .header-avatar{width:36px;height:36px;flex-shrink:0}}</style>
